/**
 * ICRA 2026 Program Browser
 * Vanilla ES-module, no build step.
 *
 * Data files (generated by scrape/):
 *   data/papers.json       — all papers with metadata
 *   data/embeddings.bin    — Float32 matrix (n_papers × 384), pre-normalised
 *   data/embeddings_meta.json — shape metadata
 */

// ── Transformers.js (ONNX, runs in-browser) ──────────────────────────────────
import { pipeline, env } from 'https://cdn.jsdelivr.net/npm/@xenova/transformers@2.17.2/dist/transformers.min.js';
env.allowLocalModels = false;

// ── State ─────────────────────────────────────────────────────────────────────
const S = {
  papers: [],
  keywords: [],
  sessionTypes: [],

  embeddings: null,   // Float32Array, length = n_papers × DIM
  embDim: 384,

  model: null,
  modelReady: false,
  modelError: false,

  semanticScores: null,   // Float32Array, one score per paper

  filter: {
    day: '',            // '' = all
    types: new Set(),
    keywords: new Set(),
    author: '',
    text: '',
    semanticQuery: '',
  },

  sort: 'time',         // 'relevance' | 'time' | 'title'
  displayCount: 50,
  resultIndices: [],    // indices into S.papers, filtered + sorted
  bookmarks: new Set(), // paper IDs
};

// Day ordering for chronological sort
const DAY_ORDER = { Sunday: 0, Monday: 1, Tuesday: 2, Wednesday: 3, Thursday: 4, Friday: 5 };

// ── Utilities ─────────────────────────────────────────────────────────────────
const $ = id => document.getElementById(id);
const esc = s => (s ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function debounce(fn, ms) {
  let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); };
}

function getSessionTypeClass(type = '') {
  const t = type.toLowerCase();
  if (t.includes('award'))                    return 'type-award';
  if (t.includes('keynote') || t.includes('plenary')) return 'type-keynote';
  if (t.includes('invited'))                  return 'type-invited';
  if (t.includes('interactive') || t.includes('poster')) return 'type-interactive';
  if (t.includes('panel'))                    return 'type-panel';
  if (t.includes('workshop'))                 return 'type-workshop';
  if (t.includes('tutorial'))                 return 'type-tutorial';
  if (t.includes('late') || t.includes('breaking')) return 'type-late';
  return 'type-regular';
}

// Dot-product of two Float32Array slices (embeddings are pre-normalised)
function dotSlice(a, aOff, b, bOff, dim) {
  let s = 0;
  for (let i = 0; i < dim; i++) s += a[aOff + i] * b[bOff + i];
  return s;
}

// ── Data loading ──────────────────────────────────────────────────────────────
async function loadData() {
  const res = await fetch('data/papers.json');
  if (!res.ok) throw new Error(`Failed to load papers.json: ${res.status}`);
  const data = await res.json();

  S.papers      = data.papers ?? [];
  S.keywords    = data.keywords ?? [];
  S.sessionTypes = data.sessionTypes ?? [];

  // Merge events (keynotes, panels, workshops) if available
  try {
    const evRes = await fetch('data/events.json');
    if (evRes.ok) {
      const events = await evRes.json();
      S.papers = [...S.papers, ...events];
      // Add event session types
      const evTypes = new Set(events.map(e => e.session_type).filter(Boolean));
      evTypes.forEach(t => { if (!S.sessionTypes.includes(t)) S.sessionTypes.push(t); });
      S.sessionTypes.sort((a, b) => a.localeCompare(b));
    }
  } catch { /* events.json is optional */ }

  return data;
}

async function loadEmbeddings() {
  try {
    const [metaRes, binRes] = await Promise.all([
      fetch('data/embeddings_meta.json'),
      fetch('data/embeddings.bin'),
    ]);
    if (!metaRes.ok || !binRes.ok) return; // embeddings optional
    const meta = await metaRes.json();
    const buf  = await binRes.arrayBuffer();
    S.embeddings = new Float32Array(buf);
    S.embDim = meta.dim ?? 384;
  } catch { /* embeddings are optional; semantic search will be disabled */ }
}

// ── Semantic model ────────────────────────────────────────────────────────────
async function initModel() {
  const pill  = $('model-status');
  const label = pill.querySelector('.model-label');
  try {
    label.textContent = 'Loading model…';
    S.model = await pipeline('feature-extraction', 'Xenova/all-MiniLM-L6-v2');
    S.modelReady = true;
    pill.classList.add('ready');
    label.textContent = 'Semantic ready';
    $('semantic-btn').disabled = false;
    $('semantic-hint').textContent = '';
  } catch (e) {
    S.modelError = true;
    pill.classList.add('error');
    label.textContent = 'Model unavailable';
    $('semantic-hint').textContent = 'Semantic search requires internet access to download the model (~25 MB).';
  }
}

async function runSemanticSearch(query) {
  if (!S.modelReady || !S.embeddings) return;
  const btn = $('semantic-btn');
  btn.textContent = 'Searching…';
  btn.disabled = true;
  try {
    const out = await S.model(query, { pooling: 'mean', normalize: true });
    const qEmb = out.data; // Float32Array of length DIM
    const n = S.papers.length;
    const dim = S.embDim;
    const scores = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      scores[i] = dotSlice(S.embeddings, i * dim, qEmb, 0, dim);
    }
    S.semanticScores = scores;
    S.filter.semanticQuery = query;
    S.sort = 'relevance';
    $('sort-select').value = 'relevance';
  } finally {
    btn.textContent = 'Search';
    btn.disabled = false;
  }
  applyAndRender();
}

// ── Filtering & scoring ───────────────────────────────────────────────────────
function scoreAndFilter() {
  const { day, types, keywords, author, text } = S.filter;
  const authorQ = author.toLowerCase().trim();
  const textQ   = text.toLowerCase().trim();
  const hasKw   = keywords.size > 0;
  const hasSem  = S.semanticScores !== null;

  const indices = [];
  for (let i = 0; i < S.papers.length; i++) {
    const p = S.papers[i];

    // ── Hard filters ──────────────────────────────────────────────────────────
    if (day && p.day !== day) continue;
    if (types.size && !types.has(p.session_type)) continue;
    if (authorQ) {
      const found = p.authors.some(a => a.name.toLowerCase().includes(authorQ));
      if (!found) continue;
    }
    if (textQ) {
      const inTitle    = p.title.toLowerCase().includes(textQ);
      const inAbstract = p.abstract.toLowerCase().includes(textQ);
      if (!inTitle && !inAbstract) continue;
    }

    indices.push(i);
  }

  // ── Scoring (soft filters) ────────────────────────────────────────────────
  const scores = new Map();
  if (hasKw || hasSem) {
    for (const i of indices) {
      const p = S.papers[i];
      let score = 0;
      if (hasKw) {
        let hits = 0;
        for (const kw of keywords) if (p.keywords.includes(kw)) hits++;
        score += hits * 2;
      }
      if (hasSem) {
        score += (S.semanticScores[i] + 1) * 3; // shift from [-1,1] to [0,2], scale
      }
      scores.set(i, score);
    }
  }

  // ── Sort ──────────────────────────────────────────────────────────────────
  indices.sort((a, b) => {
    if (S.sort === 'relevance' && scores.size) {
      return (scores.get(b) ?? 0) - (scores.get(a) ?? 0);
    }
    if (S.sort === 'title') {
      return S.papers[a].title.localeCompare(S.papers[b].title);
    }
    // Default: chronological (day → time)
    const pa = S.papers[a], pb = S.papers[b];
    const dayDiff = (DAY_ORDER[pa.day] ?? 9) - (DAY_ORDER[pb.day] ?? 9);
    if (dayDiff !== 0) return dayDiff;
    return (pa.time ?? '').localeCompare(pb.time ?? '');
  });

  S.resultIndices = indices;
  S._scores = scores; // expose for rendering
}

function applyAndRender() {
  scoreAndFilter();
  S.displayCount = 50;
  renderPapers();
}

// ── Rendering ─────────────────────────────────────────────────────────────────
function renderPapers() {
  const list = $('papers-list');
  const slice = S.resultIndices.slice(0, S.displayCount);
  const hasKw = S.filter.keywords.size > 0;
  const hasSem = S.semanticScores !== null;

  if (S.resultIndices.length === 0) {
    list.innerHTML = '<div class="empty-state">No papers match the current filters.</div>';
    $('load-more-btn').classList.add('hidden');
    $('results-count').textContent = '0 papers';
    return;
  }

  const html = slice.map(i => {
    const p = S.papers[i];
    const bm = S.bookmarks.has(p.id);
    const score = S._scores?.get(i);
    const typeClass = getSessionTypeClass(p.session_type);

    const authors = p.authors
      .map(a => `${esc(a.name)}${a.affiliation ? ` <span class="aff">(${esc(a.affiliation)})</span>` : ''}`)
      .join(', ');

    const kwHtml = p.keywords.map(k => {
      const active = S.filter.keywords.has(k) ? ' kw-active' : '';
      return `<span class="paper-kw${active}" data-kw="${esc(k)}">${esc(k)}</span>`;
    }).join('');

    const scoreHtml = (hasKw || hasSem) && score !== undefined
      ? `<div class="paper-score">Relevance score: ${score.toFixed(2)}</div>` : '';

    const abstractHtml = p.abstract
      ? `<div class="paper-abstract">
           <button class="toggle-abstract">Show abstract ▼</button>
           <div class="abstract-body hidden">${esc(p.abstract)}</div>
         </div>` : '';

    return `
<div class="paper-card${bm ? ' is-bookmarked' : ''}" data-id="${esc(p.id)}" data-idx="${i}">
  <div class="card-header">
    <div class="card-meta">
      <span class="session-badge ${typeClass}">${esc(p.session_type)}</span>
      <span class="paper-id">${esc(p.id)}</span>
      <span class="paper-time">${esc(p.day?.slice(0,3) ?? '')} ${esc(p.time ?? '')}</span>
      ${p.room ? `<span class="paper-room">${esc(p.room)}</span>` : ''}
    </div>
    <button class="btn-bm${bm ? ' bookmarked' : ''}" data-id="${esc(p.id)}" title="${bm ? 'Remove bookmark' : 'Bookmark'}">${bm ? '★' : '☆'}</button>
  </div>
  <h3 class="paper-title">${esc(p.title)}</h3>
  <div class="paper-authors">${authors}</div>
  ${kwHtml ? `<div class="paper-kws">${kwHtml}</div>` : ''}
  ${abstractHtml}
  ${p.url ? `<div class="paper-ext-link"><a href="${esc(p.url)}" target="_blank" rel="noopener">↗ Workshop website</a></div>` : ''}
  ${scoreHtml}
</div>`;
  }).join('');

  list.innerHTML = html;

  const remaining = S.resultIndices.length - S.displayCount;
  const btn = $('load-more-btn');
  if (remaining > 0) {
    btn.classList.remove('hidden');
    btn.textContent = `Show ${Math.min(50, remaining)} more (${remaining} remaining)`;
  } else {
    btn.classList.add('hidden');
  }

  $('results-count').textContent =
    `${S.resultIndices.length.toLocaleString()} paper${S.resultIndices.length !== 1 ? 's' : ''}` +
    (S.papers.length !== S.resultIndices.length ? ` of ${S.papers.length.toLocaleString()}` : '');
}

// ── Bookmarks ─────────────────────────────────────────────────────────────────
function saveBookmarks() {
  localStorage.setItem('icra26-bookmarks', JSON.stringify([...S.bookmarks]));
}

function loadBookmarks() {
  try {
    const stored = localStorage.getItem('icra26-bookmarks');
    if (stored) S.bookmarks = new Set(JSON.parse(stored));
  } catch { /* ignore */ }
}

function updateBookmarkCount() {
  const n = S.bookmarks.size;
  $('bookmark-count').textContent = n;
  $('bm-count').textContent = n;
}

function toggleBookmark(paperId) {
  if (S.bookmarks.has(paperId)) {
    S.bookmarks.delete(paperId);
  } else {
    S.bookmarks.add(paperId);
  }
  saveBookmarks();
  updateBookmarkCount();
  // Update card UI without full re-render
  const card = document.querySelector(`.paper-card[data-id="${CSS.escape(paperId)}"]`);
  if (card) {
    card.classList.toggle('is-bookmarked', S.bookmarks.has(paperId));
    const btn = card.querySelector('.btn-bm');
    const bm = S.bookmarks.has(paperId);
    if (btn) {
      btn.classList.toggle('bookmarked', bm);
      btn.textContent = bm ? '★' : '☆';
      btn.title = bm ? 'Remove bookmark' : 'Bookmark';
    }
  }
  renderBookmarks();
}

function sortedBookmarks() {
  return S.papers
    .filter(p => S.bookmarks.has(p.id))
    .sort((a, b) => {
      const dd = (DAY_ORDER[a.day] ?? 9) - (DAY_ORDER[b.day] ?? 9);
      if (dd !== 0) return dd;
      const td = (a.time ?? '').localeCompare(b.time ?? '');
      if (td !== 0) return td;
      return (a.session_id ?? '').localeCompare(b.session_id ?? '');
    });
}

// Returns Map<day, Map<timeSlot, paper[]>>
function buildSchedule(papers) {
  const days = new Map();
  for (const p of papers) {
    const day = p.day ?? 'Unknown';
    const slot = p.time ?? 'TBD';
    if (!days.has(day)) days.set(day, new Map());
    const slots = days.get(day);
    if (!slots.has(slot)) slots.set(slot, []);
    slots.get(slot).push(p);
  }
  return days;
}

function renderBookmarks() {
  const list = $('bookmarks-list');
  if (S.bookmarks.size === 0) {
    list.innerHTML = '<p class="hint">No bookmarks yet. Click ☆ on any paper.</p>';
  } else {
    const bmPapers = sortedBookmarks();
    list.innerHTML = bmPapers.map(p => `
<div class="bm-item">
  <div class="bm-item-meta">${esc(p.id)} · ${esc(p.day?.slice(0,3) ?? '')} ${esc(p.time ?? '')} · ${esc(p.room ?? '')}</div>
  <div class="bm-item-title">${esc(p.title)}</div>
  <div class="bm-item-authors">${p.authors.map(a => esc(a.name)).join(', ')}</div>
  <button class="bm-remove" data-id="${esc(p.id)}" title="Remove">✕</button>
</div>`).join('');
  }
  renderPlan();
}

function renderPlan() {
  const el = $('plan-view');
  if (S.bookmarks.size === 0) {
    el.innerHTML = '<p class="hint">No bookmarks yet. Click ☆ on any paper.</p>';
    return;
  }
  el.innerHTML = planHTML(sortedBookmarks(), false);
}

function planHTML(papers, forPrint) {
  const schedule = buildSchedule(papers);
  const sortedDays = [...schedule.keys()].sort((a, b) => (DAY_ORDER[a] ?? 9) - (DAY_ORDER[b] ?? 9));
  const dayClass  = forPrint ? 'print-plan-day'      : 'plan-day';
  const slotClass = forPrint ? 'print-plan-slot'     : 'plan-slot';
  const confClass = forPrint ? 'print-plan-conflict' : 'plan-conflict';
  const entryClass= forPrint ? 'print-plan-entry'    : 'plan-entry';
  const roomClass = forPrint ? 'print-plan-room'     : 'plan-room';
  const titleClass= forPrint ? 'print-plan-title'    : 'plan-title';

  const html = [];
  for (const day of sortedDays) {
    html.push(`<div class="${dayClass}">${esc(day)}</div>`);
    const slots = schedule.get(day);
    const sortedSlots = [...slots.keys()].sort();
    for (const slot of sortedSlots) {
      const papers = slots.get(slot);
      const rooms = new Set(papers.map(p => p.room ?? ''));
      const conflict = rooms.size > 1;
      html.push(`<div class="${slotClass}${conflict ? ' ' + confClass : ''}">`);
      html.push(`<div class="plan-slot-time">${conflict ? '⚠ ' : ''}${esc(slot)}</div>`);
      for (const p of papers) {
        html.push(`<div class="${entryClass}">
  <span class="${roomClass}">${esc(p.room ?? '—')}</span>
  <span class="${titleClass}">${esc(p.title)}</span>
</div>`);
      }
      html.push(`</div>`);
    }
  }
  return html.join('');
}

// ── PDF export ────────────────────────────────────────────────────────────────
function exportPDF() {
  const showAbstracts = document.getElementById('pdf-abstracts').checked;
  const bmPapers = sortedBookmarks();

  // Plan summary page
  $('print-plan').innerHTML =
    `<h2 class="print-plan-heading">Schedule Overview</h2>` + planHTML(bmPapers, true);

  // Paper details grouped chronologically
  const html = [];
  let lastDay = null, lastSlot = null;
  for (const p of bmPapers) {
    const day = p.day ?? 'Unknown';
    const slot = p.time ?? '';
    const slotLabel = slot ? `${day},${slot}` : day;

    if (day !== lastDay) {
      html.push(`<div class="print-day-header">${esc(day)}</div>`);
      lastDay = day;
      lastSlot = null;
    }
    if (slotLabel !== lastSlot) {
      html.push(`<div class="print-slot-header">${esc(slot)}${p.room ? ' · ' + esc(p.room) : ''}</div>`);
      lastSlot = slotLabel;
    }
    html.push(`
<div class="print-paper">
  <div class="print-paper-meta">${esc(p.session_type)}${p.session_title ? ' · ' + esc(p.session_title) : ''}</div>
  <div class="print-paper-title">${esc(p.title)}</div>
  <div class="print-paper-authors">${p.authors.map(a => esc(a.name) + (a.affiliation ? ` (${esc(a.affiliation)})` : '')).join('; ')}</div>
  ${p.keywords.length ? `<div class="print-paper-kws">${p.keywords.map(esc).join(', ')}</div>` : ''}
  ${showAbstracts && p.abstract ? `<div class="print-paper-abstract">${esc(p.abstract)}</div>` : ''}
</div>`);
  }

  $('print-papers').innerHTML = html.join('');
  window.print();
}

// ── Keyword autocomplete ──────────────────────────────────────────────────────
function updateKeywordDropdown(query) {
  const dd = $('keyword-dropdown');
  if (!query) { dd.classList.add('hidden'); return; }
  const q = query.toLowerCase();
  const matches = S.keywords
    .filter(k => !S.filter.keywords.has(k) && k.toLowerCase().includes(q))
    .slice(0, 12);
  if (matches.length === 0) { dd.classList.add('hidden'); return; }
  dd.innerHTML = matches.map(k => `<li data-kw="${esc(k)}">${esc(k)}</li>`).join('');
  dd.classList.remove('hidden');
}

function addKeyword(kw) {
  S.filter.keywords.add(kw);
  renderKeywordTags();
  $('keyword-input').value = '';
  $('keyword-dropdown').classList.add('hidden');
  if (S.sort === 'time') { S.sort = 'relevance'; $('sort-select').value = 'relevance'; }
  applyAndRender();
}

function removeKeyword(kw) {
  S.filter.keywords.delete(kw);
  renderKeywordTags();
  applyAndRender();
}

function renderKeywordTags() {
  $('keyword-tags').innerHTML = [...S.filter.keywords].map(k =>
    `<span class="kw-tag">${esc(k)}<button class="remove-kw" data-kw="${esc(k)}" title="Remove">×</button></span>`
  ).join('');
}

// ── Session type checkboxes ───────────────────────────────────────────────────
function buildTypeFilters() {
  const container = $('type-filters');
  container.innerHTML = S.sessionTypes.map(t => `
<label>
  <input type="checkbox" name="type" value="${esc(t)}">
  ${esc(t)}
</label>`).join('');
}

// ── Event wiring ──────────────────────────────────────────────────────────────
function wireEvents() {
  // Day chips
  $('day-chips').addEventListener('click', e => {
    const btn = e.target.closest('.chip');
    if (!btn) return;
    document.querySelectorAll('#day-chips .chip').forEach(c => c.classList.remove('active'));
    btn.classList.add('active');
    S.filter.day = btn.dataset.day;
    applyAndRender();
  });

  // Session type checkboxes
  $('type-filters').addEventListener('change', () => {
    S.filter.types = new Set(
      [...document.querySelectorAll('#type-filters input:checked')].map(el => el.value)
    );
    applyAndRender();
  });

  // Keyword input
  const kwInput = $('keyword-input');
  kwInput.addEventListener('input', debounce(() => updateKeywordDropdown(kwInput.value.trim()), 150));
  kwInput.addEventListener('keydown', e => {
    if (e.key === 'Escape') { $('keyword-dropdown').classList.add('hidden'); }
    if (e.key === 'Enter') {
      const first = $('keyword-dropdown').querySelector('li');
      if (first) addKeyword(first.dataset.kw);
    }
  });
  kwInput.addEventListener('blur', () => setTimeout(() => $('keyword-dropdown').classList.add('hidden'), 200));

  $('keyword-dropdown').addEventListener('mousedown', e => {
    const li = e.target.closest('li');
    if (li) addKeyword(li.dataset.kw);
  });

  // Keyword tag removal
  $('keyword-tags').addEventListener('click', e => {
    const btn = e.target.closest('.remove-kw');
    if (btn) removeKeyword(btn.dataset.kw);
  });

  // Author input
  $('author-input').addEventListener('input', debounce(e => {
    S.filter.author = e.target.value;
    applyAndRender();
  }, 300));

  // Text input
  $('text-input').addEventListener('input', debounce(e => {
    S.filter.text = e.target.value;
    applyAndRender();
  }, 300));

  // Semantic search
  $('semantic-btn').addEventListener('click', () => {
    const q = $('semantic-input').value.trim();
    if (q) runSemanticSearch(q);
  });
  $('semantic-input').addEventListener('keydown', e => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      const q = $('semantic-input').value.trim();
      if (q && S.modelReady) runSemanticSearch(q);
    }
  });

  // Sort
  $('sort-select').addEventListener('change', e => {
    S.sort = e.target.value;
    applyAndRender();
  });

  // Load more
  $('load-more-btn').addEventListener('click', () => {
    S.displayCount += 50;
    renderPapers();
  });

  // Paper list (event delegation)
  $('papers-list').addEventListener('click', e => {
    // Bookmark toggle
    const bmBtn = e.target.closest('.btn-bm');
    if (bmBtn) { toggleBookmark(bmBtn.dataset.id); return; }

    // Abstract toggle
    const toggleBtn = e.target.closest('.toggle-abstract');
    if (toggleBtn) {
      const body = toggleBtn.nextElementSibling;
      const open = body.classList.toggle('hidden');
      toggleBtn.textContent = open ? 'Show abstract ▼' : 'Hide abstract ▲';
      return;
    }

    // Keyword chip click → add to filter
    const kwTag = e.target.closest('.paper-kw');
    if (kwTag) {
      addKeyword(kwTag.dataset.kw);
      return;
    }
  });

  // Filters drawer (mobile)
  const sidebar = document.getElementById('sidebar');
  const sidebarOverlay = $('sidebar-overlay');
  $('filters-btn').addEventListener('click', () => {
    sidebar.classList.add('open');
    sidebarOverlay.classList.remove('hidden');
  });
  sidebarOverlay.addEventListener('click', () => {
    sidebar.classList.remove('open');
    sidebarOverlay.classList.add('hidden');
  });

  // Bookmarks panel
  $('bookmarks-btn').addEventListener('click', openBookmarks);
  $('close-bm-btn').addEventListener('click', closeBookmarks);
  $('bm-overlay').addEventListener('click', closeBookmarks);
  $('export-pdf-btn').addEventListener('click', exportPDF);

  $('bookmarks-list').addEventListener('click', e => {
    const btn = e.target.closest('.bm-remove');
    if (btn) toggleBookmark(btn.dataset.id);
  });

  // Plan / List tab switching
  document.querySelectorAll('.bm-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.bm-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      const isPlan = tab.dataset.tab === 'plan';
      $('bookmarks-list').classList.toggle('hidden', isPlan);
      $('plan-view').classList.toggle('hidden', !isPlan);
    });
  });

  // Clear all
  $('clear-btn').addEventListener('click', clearAllFilters);
}

function openBookmarks() {
  renderBookmarks();
  $('bookmarks-panel').classList.remove('hidden');
  $('bm-overlay').classList.remove('hidden');
}

function closeBookmarks() {
  $('bookmarks-panel').classList.add('hidden');
  $('bm-overlay').classList.add('hidden');
}

function clearAllFilters() {
  S.filter = { day: '', types: new Set(), keywords: new Set(), author: '', text: '', semanticQuery: '' };
  S.semanticScores = null;
  S.sort = 'time';

  document.querySelectorAll('#day-chips .chip').forEach((c, i) => c.classList.toggle('active', i === 0));
  document.querySelectorAll('#type-filters input').forEach(el => el.checked = false);
  $('keyword-input').value = '';
  $('keyword-tags').innerHTML = '';
  $('author-input').value = '';
  $('text-input').value = '';
  $('semantic-input').value = '';
  $('sort-select').value = 'time';

  applyAndRender();
}

// ── Bootstrap ─────────────────────────────────────────────────────────────────
async function main() {
  loadBookmarks();
  updateBookmarkCount();
  wireEvents();

  // Load model in background — don't block the UI
  initModel();

  try {
    await loadData();
  } catch (e) {
    $('papers-list').innerHTML =
      `<div class="empty-state">⚠️ Could not load program data.<br>
       <small>Run <code>scrape/scrape.py</code> to generate <code>docs/data/papers.json</code>, then serve this folder.</small></div>`;
    return;
  }

  buildTypeFilters();

  // Load embeddings in background (optional)
  loadEmbeddings();

  applyAndRender();
}

main();
